class ContactViewTest extends SpringBrowserlessTest {

    @Test
    void initialStateIsEmptyAndSendIsEnabled() {
        navigate(ContactView.class);

        assertThat($(H1.class).withText("Contact").exists()).isTrue();
        assertThat($(TextField.class).withLabel("Name").single().getValue()).isEmpty();
        assertThat($(EmailField.class).withLabel("Email").single().getValue()).isEmpty();
        assertThat($(TextField.class).withLabel("Phone").single().getValue()).isEmpty();
        assertThat($(TextArea.class).withLabel("Message").single().getValue()).isEmpty();

        Button send = $(Button.class).withText("Send").single();
        assertThat(send.isEnabled()).isTrue();
    }

    @Test
    void sendingEmptyFormShowsErrorsAndSendsNothing() {
        navigate(ContactView.class);

        Button send = $(Button.class).withText("Send").single();
        test(send).click();

        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();

        assertThat(name.isInvalid()).isTrue();
        assertThat(name.getErrorMessage()).isEqualTo("Name is required");

        assertThat(email.isInvalid()).isTrue();
        assertThat(email.getErrorMessage()).isEqualTo("Give an e-mail address or a phone number");

        assertThat(message.isInvalid()).isTrue();
        assertThat(message.getErrorMessage()).isEqualTo("Message is required");

        Grid<?> grid = $(Grid.class).single();
        assertThat(test(grid).size()).isZero();
    }

    @Test
    void invalidEmailFormatIsRejected() {
        navigate(ContactView.class);

        test($(TextField.class).withLabel("Name").single()).setValue("Ada");
