        test($(TextArea.class).withLabel("Message").single()).setValue("Hello there");

        test($(Button.class).withText("Send").single()).click();

        EmailField email = $(EmailField.class).withLabel("Email").single();
        assertThat(email.isInvalid()).isTrue();
        assertThat(email.getErrorMessage()).isEqualTo("Enter a valid e-mail address");
    }

