+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    private static final int MESSAGE_MAX_LENGTH = 500;
+
+    private final MessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> grid = new Grid<>(Message.class, false);
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(this::reenableSendIfFromClient);
+        email.addValueChangeListener(this::reenableSendIfFromClient);
+        phone.addValueChangeListener(this::reenableSendIfFromClient);
+        message.addValueChangeListener(this::reenableSendIfFromClient);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        add(form, send);
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::email).setHeader("Email");
+        grid.addColumn(Message::phone).setHeader("Phone");
+        grid.addColumn(Message::text).setHeader("Message");
+        grid.addColumn(m -> DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
+                .withZone(ZoneId.systemDefault()).format(m.sentAt())).setHeader("Sent");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void reenableSendIfFromClient(HasValue.ValueChangeEvent<?> event) {
+        if (event.isFromClient()) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void trySend() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        if (!emailValue.isBlank() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (messageValue.length() > MESSAGE_MAX_LENGTH) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageService.add(new Message(name.getValue(), emailValue, phoneValue, messageValue));
+
+        Notification notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+
+        refreshGrid();
+        send.setEnabled(false);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.getMessages());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isBlank() || !email.getValue().isBlank()
+                || !phone.getValue().isBlank() || !message.getValue().isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Span("You have unsent input. Do you want to discard it?"));
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.getFooter().add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
